{
  "company": "NTPC",
  "base_year": 2021,
  "strategy": "baseline",
  "assumptions": [
    {
      "assumption": "Revenue grows at a steady ~5% per annum (extrapolated from the FY2020-21 YoY rate of ~1.89%, implicitly smoothed upward), implying stable tariff realisation and full plant load factor (PLF) utilisation across NTPC's fleet.",
      "failure_scenario": "A significant shortfall in coal availability (as experienced during India's coal supply crises) or a weaker-than-expected power demand environment could suppress PLF and regulated tariff billing, causing revenue growth to stagnate at 1-2% or even decline — well below the ~5% assumed trajectory.",
      "risk": "High"
    },
    {
      "assumption": "Net income grows at a moderated ~4.92% per annum, treating FY2021's elevated PAT as a normalised base and assuming the effective tax rate stabilises at post-FY2020 levels going forward.",
      "failure_scenario": "If NTPC faces accelerated depreciation charges from new capacity additions, higher-than-expected finance costs from its aggressive capex programme, or a regulatory disallowance of certain cost pass-throughs by CERC, net income growth could be materially lower — or negative — irrespective of revenue performance, making the 4.92% growth rate unsustainable.",
      "risk": "High"
    },
    {
      "assumption": "Shares outstanding remain fixed at ~984.47 crore for all three forecast years, implying no equity dilution via QIPs, rights issues, or ESOP conversions through FY2024.",
      "failure_scenario": "NTPC's large capital expenditure pipeline for renewable energy capacity additions may necessitate equity fundraising (e.g., a QIP or rights issue), increasing the share count and diluting EPS below projected levels even if net income meets expectations.",
      "risk": "Medium"
    }
  ],
  "confidence_score": 38,
